begin;
with j as (select * from jsonb_to_recordset($law7d0031$[{"code_id":"GK_RF_2","article_number":"1086","version_date":"1994-11-30","article_text":"1. Размер подлежащего возмещению утраченного потерпевшим заработка (дохода) определяется в процентах к его среднему месячному заработку (доходу) до увечья или иного повреждения здоровья либо до утраты им трудоспособности, соответствующих степени утраты потерпевшим профессиональной трудоспособности, а при отсутствии профессиональной трудоспособности - степени утраты общей трудоспособности.\n\n2. В состав утраченного заработка (дохода) потерпевшего включаются все виды оплаты его труда по трудовым и гражданско-правовым договорам как по месту основной работы, так и по совместительству, облагаемые подоходным налогом. Не учитываются выплаты единовременного характера, в частности компенсация за неиспользованный отпуск и выходное пособие при увольнении. За период временной нетрудоспособности или отпуска по беременности и родам учитывается выплаченное пособие. Доходы от предпринимательской деятельности, а также авторский гонорар включаются в состав утраченного заработка, при этом доходы от предпринимательской деятельности включаются на основании данных налоговой инспекции.\n\nВсе виды заработка (дохода) учитываются в суммах, начисленных до удержания налогов.\n\n3. Среднемесячный заработок (доход) потерпевшего подсчитывается путем деления общей суммы его заработка (дохода) за двенадцать месяцев работы, предшествовавших повреждению здоровья, на двенадцать. В случае, когда потерпевший ко времени причинения вреда работал менее двенадцати месяцев, среднемесячный заработок (доход) подсчитывается путем деления общей суммы заработка (дохода) за фактически проработанное число месяцев, предшествовавших повреждению здоровья, на число этих месяцев.\n\nНе полностью проработанные потерпевшим месяцы по его желанию заменяются предшествующими полностью проработанными месяцами либо исключаются из подсчета при невозможности их замены.","article_title":"Статья 1086. Определение заработка (дохода), утраченного в результате повреждения здоровья","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3d23fcb3ae3f68eb7664595f8da87b307e0b42b6f415d0a9c0c3df92ead7800a"},{"code_id":"GK_RF_2","article_number":"1087","version_date":"1994-11-30","article_text":"1. В случае увечья или иного повреждения здоровья несовершеннолетнего, не достигшего четырнадцати лет (малолетнего) и не имеющего заработка (дохода), лицо, ответственное за причиненный вред, обязано возместить расходы, вызванные повреждением здоровья.","article_title":"Статья 1087. Возмещение вреда при повреждении здоровья лица, не достигшего совершеннолетия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6fb8569a0ceba4e631eb4c7daa542d1145479e75eb58b35598122e5133a228b"},{"code_id":"GK_RF_2","article_number":"1088","version_date":"1994-11-30","article_text":"1. В случае смерти потерпевшего (кормильца) право на возмещение вреда имеют:\n\nнетрудоспособные лица, состоявшие на иждивении умершего или имевшие ко дню его смерти право на получение от него содержания;\n\nребенок умершего, родившийся после его смерти;\n\nодин из родителей, супруг либо другой член семьи независимо от его трудоспособности, который не работает и занят уходом за находившимися на иждивении умершего его детьми, внуками, братьями и сестрами, не достигшими четырнадцати лет либо хотя и достигшими указанного возраста, но по заключению медицинских органов нуждающимися по состоянию здоровья в постороннем уходе;\n\nлица, состоявшие на иждивении умершего и ставшие нетрудоспособными в течение пяти лет после его смерти.\n\nОдин из родителей, супруг либо другой член семьи, не работающий и занятый уходом за детьми, внуками, братьями и сестрами умершего и ставший нетрудоспособным в период осуществления ухода, сохраняет право на возмещение вреда после окончания ухода за этими лицами.\n\n2. Вред возмещается:\n\nнесовершеннолетним - до достижения восемнадцати лет;\n\nобучающимся старше восемнадцати лет - до получения образования по очной форме обучения, но не более чем до двадцати трех лет; (В редакции Федерального закона от 02.07.2013 № 185-ФЗ)\n\nженщинам старше пятидесяти пяти лет и мужчинам старше шестидесяти лет - пожизненно;\n\nинвалидам - на срок инвалидности;\n\nодному из родителей, супругу либо другому члену семьи, занятому уходом за находившимися на иждивении умершего его детьми, внуками, братьями и сестрами, - до достижения ими четырнадцати лет либо изменения состояния здоровья.","article_title":"Статья 1088. Возмещение вреда лицам, понесшим ущерб в результате смерти кормильца","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c975b9cda939e9e862850627fd167caa094e1819bdc0f1787f21ea21a07309c"},{"code_id":"GK_RF_2","article_number":"1089","version_date":"1994-11-30","article_text":"1. Лицам, имеющим право на возмещение вреда в связи со смертью кормильца, вред возмещается в размере той доли заработка (дохода) умершего, определенного по правилам статьи 1086 настоящего Кодекса, которую они получали или имели право получать на свое содержание при его жизни. При определении возмещения вреда этим лицам в состав доходов умершего наряду с заработком (доходом) включаются получаемые им при жизни пенсия, пожизненное содержание и другие подобные выплаты.\n\n2. При определении размера возмещения вреда пенсии, назначенные лицам в связи со смертью кормильца, а равно другие виды пенсий, назначенные как до, так и после смерти кормильца, а также заработок (доход) и стипендия, получаемые этими лицами, в счет возмещения им вреда не засчитываются.\n\n3. Установленный каждому из имеющих право на возмещение вреда в связи со смертью кормильца размер возмещения не подлежит дальнейшему перерасчету, кроме случаев:\n\nрождения ребенка после смерти кормильца;\n\nназначения или прекращения выплаты возмещения лицам, занятым уходом за детьми, внуками, братьями и сестрами умершего кормильца.\n\nЗаконом или договором может быть увеличен размер возмещения.","article_title":"Статья 1089. Размер возмещения вреда, понесенного в случае смерти кормильца","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d7693491798a962dc2b9ff14b64a285da3a75bfe8595c81213ca5290902fb82"},{"code_id":"GK_RF_2","article_number":"1090","version_date":"1994-11-30","article_text":"1. Потерпевший, частично утративший трудоспособность, вправе в любое время потребовать от лица, на которое возложена обязанность возмещения вреда, соответствующего увеличения размера его возмещения, если трудоспособность потерпевшего в дальнейшем уменьшилась в связи с причиненным повреждением здоровья по сравнению с той, которая оставалась у него к моменту присуждения ему возмещения вреда.\n\n2. Лицо, на которое возложена обязанность возмещения вреда, причиненного здоровью потерпевшего, вправе потребовать соответствующего уменьшения размера возмещения, если трудоспособность потерпевшего возросла по сравнению с той, которая была у него к моменту присуждения возмещения вреда.\n\n3. Потерпевший вправе требовать увеличения размера возмещения вреда, если имущественное положение гражданина, на которого возложена обязанность возмещения вреда, улучшилось, а размер возмещения был уменьшен в соответствии с пунктом 3 статьи 1083 настоящего Кодекса.\n\n4. Суд может по требованию гражданина, причинившего вред, уменьшить размер возмещения вреда, если его имущественное положение в связи с инвалидностью либо достижением пенсионного возраста ухудшилось по сравнению с положением на момент присуждения возмещения вреда, за исключением случаев, когда вред был причинен действиями, совершенными умышленно.","article_title":"Статья 1090. Последующее изменение размера возмещения вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"366bb615f8917f6f480ed3c1034487fb50174bda9c41fc12d18b5d1caf682f3b"},{"code_id":"GK_RF_2","article_number":"1091","version_date":"1994-11-30","article_text":"Суммы выплачиваемого гражданам возмещения вреда, причиненного жизни или здоровью потерпевшего, подлежат изменению пропорционально росту установленной в соответствии с законом величины прожиточного минимума на душу населения в соответствующем субъекте Российской Федерации по месту жительства потерпевшего, а при отсутствии в соответствующем субъекте Российской Федерации указанной величины данные суммы должны быть не менее установленной в соответствии с законом величины прожиточного минимума на душу населения в целом по Российской Федерации.\n\n(Статья в редакции Федерального закона от 30.11.2011 № 363-ФЗ)","article_title":"Статья 1091. Индексация размера возмещения вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b895969c427422f9373521d21f5a121cad500909c8a5b7527a6cb2479f47ebeb"},{"code_id":"GK_RF_2","article_number":"1092","version_date":"1994-11-30","article_text":"1. Возмещение вреда, вызванного уменьшением трудоспособности или смертью потерпевшего, производится ежемесячными платежами.\n\nПри наличии уважительных причин суд с учетом возможностей причинителя вреда может по требованию гражданина, имеющего право на возмещение вреда, присудить ему причитающиеся платежи единовременно, но не более чем за три года.\n\n2. Суммы в возмещение дополнительных расходов (пункт 1 статьи 1085) могут быть присуждены на будущее время в пределах сроков, определяемых на основе заключения медицинской экспертизы, а также при необходимости предварительной оплаты стоимости соответствующих услуг и имущества, в том числе приобретения путевки, оплаты проезда, оплаты специальных транспортных средств.","article_title":"Статья 1092. Платежи по возмещению вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7d97fbacb04d873a05dc1bc81280dcb4c7229168f1bde0ef46b071aab483ff93"},{"code_id":"GK_RF_2","article_number":"1093","version_date":"1994-11-30","article_text":"1. В случае реорганизации юридического лица, признанного в установленном порядке ответственным за вред, причиненный жизни или здоровью, обязанность по выплате соответствующих платежей несет его правопреемник. К нему же предъявляются требования о возмещении вреда.\n\n2. В случае ликвидации юридического лица, признанного в установленном порядке ответственным за вред, причиненный жизни или здоровью, соответствующие платежи должны быть капитализированы для выплаты их потерпевшему по правилам, установленным законом или иными правовыми актами.\n\nЗаконом или иными правовыми актами могут быть установлены и другие случаи, при которых может быть произведена капитализация платежей.","article_title":"Статья 1093. Возмещение вреда в случае прекращения юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fec8e1c75372ce757f151aefd21c0dac88a52f9ff61efd9275073d4cc01dfb22"},{"code_id":"GK_RF_2","article_number":"1094","version_date":"1994-11-30","article_text":"Лица, ответственные за вред, вызванный смертью потерпевшего, обязаны возместить необходимые расходы на погребение лицу, понесшему эти расходы.\n\nПособие на погребение, полученное гражданами, понесшими эти расходы, в счет возмещения вреда не засчитывается.","article_title":"Статья 1094. Возмещение расходов на погребение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dbddbcb66577d671ba41d7693f918eb0938e8b5c1a450f723e18456569f3a60e"},{"code_id":"GK_RF_2","article_number":"1095","version_date":"1994-11-30","article_text":"Вред, причиненный жизни, здоровью или имуществу гражданина либо имуществу юридического лица вследствие конструктивных, рецептурных или иных недостатков товара, работы или услуги, а также вследствие недостоверной или недостаточной информации о товаре (работе, услуге), подлежит возмещению продавцом или изготовителем товара, лицом, выполнившим работу или оказавшим услугу (исполнителем), независимо от их вины и от того, состоял потерпевший с ними в договорных отношениях или нет.\n\nПравила, предусмотренные настоящей статьей, применяются лишь в случаях приобретения товара (выполнения работы, оказания услуги) в потребительских целях, а не для использования в предпринимательской деятельности.","article_title":"Статья 1095. Основания возмещения вреда, причиненного вследствие недостатков товара, работы или услуги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1372f08a3bfb1a5779201a1daa83cb9d32a5d061957e0eed9f03c11dcbc5b305"},{"code_id":"GK_RF_2","article_number":"1096","version_date":"1994-11-30","article_text":"1. Вред, причиненный вследствие недостатков товара, подлежит возмещению по выбору потерпевшего продавцом или изготовителем товара.\n\n2. Вред, причиненный вследствие недостатков работы или услуги, подлежит возмещению лицом, выполнившим работу или оказавшим услугу (исполнителем).\n\n3. Вред, причиненный вследствие непредоставления полной или достоверной информации о товаре (работе, услуге), подлежит возмещению лицами, указанными в пунктах 1 и 2 настоящей статьи.","article_title":"Статья 1096. Лица, ответственные за вред, причиненный вследствие недостатков товара, работы или услуги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1a90664b1820cc22ee495d8d05b3efe75bf3d2baca5d81662246bf8143a1931d"},{"code_id":"GK_RF_2","article_number":"1097","version_date":"1994-11-30","article_text":"в нарушение требований закона срок годности или срок службы не установлен;\n\nлицо, которому был продан товар, для которого была выполнена работа или которому была оказана услуга, не было предупреждено о необходимых действиях по истечении срока годности или срока службы и возможных последствиях при невыполнении указанных действий либо ему не была предоставлена полная и достоверная информация о товаре (работе, услуге).\n\n(Пункт в редакции Федерального закона от 17.12.1999 № 213-ФЗ)","article_title":"Статья 1097. Сроки возмещения вреда, причиненного в результате недостатков товара, работы или услуги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"395de68c9316231d55b038c56ec864e36d23d7ef1b671e43b5034ed1f31270a4"},{"code_id":"GK_RF_2","article_number":"1098","version_date":"1994-11-30","article_text":"Продавец или изготовитель товара, исполнитель работы или услуги освобождается от ответственности в случае, если докажет, что вред возник вследствие непреодолимой силы или нарушения потребителем установленных правил пользования товаром, результатами работы, услуги или их хранения.","article_title":"Статья 1098. Основания освобождения от ответственности за вред, причиненный вследствие недостатков товара, работы или услуги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"316a6469ba78c40e59bdea1c879f5eaa41e5af5bd9a111f336a1b6aaacf15bab"},{"code_id":"GK_RF_2","article_number":"1099","version_date":"1994-11-30","article_text":"1. Основания и размер компенсации гражданину морального вреда определяются правилами, предусмотренными настоящей главой и статьей 151 настоящего Кодекса.\n\n2. Моральный вред, причиненный действиями (бездействием), нарушающими имущественные права гражданина, подлежит компенсации в случаях, предусмотренных законом.\n\n3. Компенсация морального вреда осуществляется независимо от подлежащего возмещению имущественного вреда.","article_title":"Статья 1099. Общие положения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7db4af11eefab0eeb5ed7b0301e710e7d8cb0ed9722ca9509d9ba0e2f718ee95"},{"code_id":"GK_RF_2","article_number":"1100","version_date":"1994-11-30","article_text":"Компенсация морального вреда осуществляется независимо от вины причинителя вреда в случаях, когда:\n\nвред причинен жизни или здоровью гражданина источником повышенной опасности;\n\nвред причинен гражданину в результате его незаконного осуждения, незаконного привлечения к уголовной ответственности, незаконного применения в качестве меры пресечения заключения под стражу или подписки о невыезде, незаконного наложения административного взыскания в виде ареста или исправительных работ;\n\nвред причинен распространением сведений, порочащих честь, достоинство и деловую репутацию;\n\nв иных случаях, предусмотренных законом.","article_title":"Статья 1100. Основания компенсации морального вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e92df62aeaea3c50e8257317f4c331a735efd4438339f29ab8d37cffc2bee2dc"},{"code_id":"GK_RF_2","article_number":"1101","version_date":"1994-11-30","article_text":"1. Компенсация морального вреда осуществляется в денежной форме.\n\n2. Размер компенсации морального вреда определяется судом в зависимости от характера причиненных потерпевшему физических и нравственных страданий, а также степени вины причинителя вреда в случаях, когда вина является основанием возмещения вреда. При определении размера компенсации вреда должны учитываться требования разумности и справедливости.\n\nХарактер физических и нравственных страданий оценивается судом с учетом фактических обстоятельств, при которых был причинен моральный вред, и индивидуальных особенностей потерпевшего.","article_title":"Статья 1101. Способ и размер компенсации морального вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"623e1b631144e3f775714cf2def97ffb61e9283043d3335d7cd709652986ee13"},{"code_id":"GK_RF_2","article_number":"1102","version_date":"1994-11-30","article_text":"1. Лицо, которое без установленных законом, иными правовыми актами или сделкой оснований приобрело или сберегло имущество (приобретатель) за счет другого лица (потерпевшего), обязано возвратить последнему неосновательно приобретенное или сбереженное имущество (неосновательное обогащение), за исключением случаев, предусмотренных статьей 1109 настоящего Кодекса.\n\n2. Правила, предусмотренные настоящей главой, применяются независимо от того, явилось ли неосновательное обогащение результатом поведения приобретателя имущества, самого потерпевшего, третьих лиц или произошло помимо их воли.","article_title":"Статья 1102. Обязанность возвратить неосновательное обогащение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ab764f7394fb3ca7400e437bad15b1de337042ba6cd1be207862b3a87a3ac0f0"},{"code_id":"GK_RF_2","article_number":"1103","version_date":"1994-11-30","article_text":"Поскольку иное не установлено настоящим Кодексом, другими законами или иными правовыми актами и не вытекает из существа соответствующих отношений, правила, предусмотренные настоящей главой, подлежат применению также к требованиям:\n\n1) о возврате исполненного по недействительной сделке;\n\n2) об истребовании имущества собственником из чужого незаконного владения;\n\n3) одной стороны в обязательстве к другой о возврате исполненного в связи с этим обязательством;\n\n4) о возмещении вреда, в том числе причиненного не\n\nдобросовестным поведением обогатившегося лица.Статья 1104. Возвращение неосновательного обогащения в натуре1. Имущество, составляющее неосновательное обогащение приобретателя, должно быть возвращено потерпевшему в натуре.2. Приобретатель отвечает перед потерпевшим за всякие, в том числе и за всякие случайные, недостачу или ухудшение неосновательно приобретенного или сбереженного имущества, происшедшие после того, как он узнал или должен был узнать о неосновательности обогащения. До этого момента он отвечает лишь за умысел и грубую неосторожность.Статья 1105. Возмещение стоимости неосновательного обогащения1. В случае невозможности возвратить в натуре неосновательно полученное или сбереженное имущество приобретатель должен возместить потерпевшему действительную стоимость этого имущества на момент его приобретения, а также убытки, вызванные последующим изменением стоимости имущества, если приобретатель не возместил его стоимость немедленно после того, как узнал о неосновательности обогащения.2. Лицо, неосновательно временно пользовавшееся чужим имуществом без намерения его приобрести либо чужими услугами, должно возместить потерпевшему то, что оно сберегло вследствие такого пользования, по цене, существовавшей во время, когда закончилось пользование, и в том месте, где оно происходило.Статья 1106. Последствия неосновательной передачи права другому лицуЛицо, передавшее путем уступки требования или иным образом принадлежащее ему право другому лицу на основании несуществующего или недействительного обязательства, вправе требовать восстановления прежнего положения, в том числе возвращения ему документов, удостоверяющих переданное право.Статья 1107. Возмещение потерпевшему неполученных доходов1. Лицо, которое неосновательно получило или сберегло имущество, обязано возвратить или возместить потерпевшему все доходы, которые оно извлекло или должно было извлечь из этого имущества с того времени, когда узнало или должно было узнать о неосновательности обогащения.2. На сумму неосновательного денежного обогащения подлежат начислению проценты за пользование чужими средствами (статья 395) с того времени, когда приобретатель узнал или должен был узнать о неосновательности получения или сбережения денежных средств.Статья 1108. Возмещение затрат на имущество, подлежащее возвратуПри возврате неосновательно полученного или сбереженного имущества (статья 1104) или возмещении его стоимости (статья 1105) приобретатель вправе требовать от потерпевшего возмещения понесенных необходимых затрат на содержание и сохранение имущества с того времени, с которого он обязан возвратить доходы (пункт 1 статьи 1107) с зачетом полученных им выгод. Право на возмещение затрат утрачивается в случае, когда приобретатель умышленно удерживал имущество, подлежащее возврату. (В редакции Федерального закона от 23.05.2018 № 116-ФЗ)Статья 1109. Неосновательное обогащение, не подлежащее возвратуНе подлежат возврату в качестве неосновательного обогащения:1) имущество, переданное во исполнение обязательства до наступления срока исполнения, если обязательством не предусмотрено иное;2) имущество, переданное во исполнение обязательства по истечении срока исковой давности;3) заработная плата и приравненные к ней платежи, пенсии, пособия, стипендии, возмещение вреда, причиненного жизни или здоровью, алименты и иные денежные суммы, предоставленные гражданину в качестве средства к существованию, при отсутствии недобросовестности с его стороны и счетной ошибки;4) денежные суммы и иное имущество, предоставленные во исполнение несуществующего обязательства, если приобретатель докажет, что лицо, требующее возврата имущества, знало об отсутствии обязательства либо предоставило имущество в целях благотворительности.Президент Российской Федерации                               Б.ЕльцинМосква, Кремль26 января 1996 года№ 14-ФЗ\n\nдобросовестным поведением обогатившегося лица.","article_title":"Статья 1103. Соотношение требований о возврате неосновательного обогащения с другими требованиями о защите гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"79b1efe16e3c68f271f8fb37b2611d1e28f9c1a0c694166132928193eb65b7b8"},{"code_id":"GK_RF_2","article_number":"1104","version_date":"1994-11-30","article_text":"1. Имущество, составляющее неосновательное обогащение приобретателя, должно быть возвращено потерпевшему в натуре.\n\n2. Приобретатель отвечает перед потерпевшим за всякие, в том числе и за всякие случайные, недостачу или ухудшение неосновательно приобретенного или сбереженного имущества, происшедшие после того, как он узнал или должен был узнать о неосновательности обогащения. До этого момента он отвечает лишь за умысел и грубую неосторожность.","article_title":"Статья 1104. Возвращение неосновательного обогащения в натуре","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cf84bf1e811a542be16fe6e08b98e6795b580dd62c965a2449e943f02010addb"},{"code_id":"GK_RF_2","article_number":"1105","version_date":"1994-11-30","article_text":"1. В случае невозможности возвратить в натуре неосновательно полученное или сбереженное имущество приобретатель должен возместить потерпевшему действительную стоимость этого имущества на момент его приобретения, а также убытки, вызванные последующим изменением стоимости имущества, если приобретатель не возместил его стоимость немедленно после того, как узнал о неосновательности обогащения.\n\n2. Лицо, неосновательно временно пользовавшееся чужим имуществом без намерения его приобрести либо чужими услугами, должно возместить потерпевшему то, что оно сберегло вследствие такого пользования, по цене, существовавшей во время, когда закончилось пользование, и в том месте, где оно происходило.","article_title":"Статья 1105. Возмещение стоимости неосновательного обогащения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"101157eb211cb69e093a1cc2ce2318b0c1d6e35990ec804f46d12f2957cab88d"},{"code_id":"GK_RF_2","article_number":"1106","version_date":"1994-11-30","article_text":"Лицо, передавшее путем уступки требования или иным образом принадлежащее ему право другому лицу на основании несуществующего или недействительного обязательства, вправе требовать восстановления прежнего положения, в том числе возвращения ему документов, удостоверяющих переданное право.","article_title":"Статья 1106. Последствия неосновательной передачи права другому лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2ca59f2a6cea25f91fbea12cc5c07ed3abfcf4eebf44009100af8e216e1f8e2"},{"code_id":"GK_RF_2","article_number":"1107","version_date":"1994-11-30","article_text":"1. Лицо, которое неосновательно получило или сберегло имущество, обязано возвратить или возместить потерпевшему все доходы, которые оно извлекло или должно было извлечь из этого имущества с того времени, когда узнало или должно было узнать о неосновательности обогащения.\n\n2. На сумму неосновательного денежного обогащения подлежат начислению проценты за пользование чужими средствами (статья 395) с того времени, когда приобретатель узнал или должен был узнать о неосновательности получения или сбережения денежных средств.","article_title":"Статья 1107. Возмещение потерпевшему неполученных доходов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"518dbeadd2b365805ca4f769f8e1e636557ad3eddce0246dac488db61d85bbce"},{"code_id":"GK_RF_2","article_number":"1108","version_date":"1994-11-30","article_text":"При возврате неосновательно полученного или сбереженного имущества (статья 1104) или возмещении его стоимости (статья 1105) приобретатель вправе требовать от потерпевшего возмещения понесенных необходимых затрат на содержание и сохранение имущества с того времени, с которого он обязан возвратить доходы (пункт 1 статьи 1107) с зачетом полученных им выгод. Право на возмещение затрат утрачивается в случае, когда приобретатель умышленно удерживал имущество, подлежащее возврату. (В редакции Федерального закона от 23.05.2018 № 116-ФЗ)","article_title":"Статья 1108. Возмещение затрат на имущество, подлежащее возврату","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"01ef7ed6c0418c1add3febe8effc5b47e8d5a5106f824d81693648ff52672687"},{"code_id":"GK_RF_2","article_number":"1109","version_date":"1994-11-30","article_text":"Не подлежат возврату в качестве неосновательного обогащения:\n\n1) имущество, переданное во исполнение обязательства до наступления срока исполнения, если обязательством не предусмотрено иное;\n\n2) имущество, переданное во исполнение обязательства по истечении срока исковой давности;\n\n3) заработная плата и приравненные к ней платежи, пенсии, пособия, стипендии, возмещение вреда, причиненного жизни или здоровью, алименты и иные денежные суммы, предоставленные гражданину в качестве средства к существованию, при отсутствии недобросовестности с его стороны и счетной ошибки;\n\n4) денежные суммы и иное имущество, предоставленные во исполнение несуществующего обязательства, если приобретатель докажет, что лицо, требующее возврата имущества, знало об отсутствии обязательства либо предоставило имущество в целях благотворительности.\n\nПрезидент Российской Федерации                               Б.Ельцин\n\nМосква, Кремль\n\n26 января 1996 года","article_title":"Статья 1109. Неосновательное обогащение, не подлежащее возврату","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd91d48afdd41aa5e9afdb7061553e98e16696b4713483a7400cb3a0b684f8e8"},{"code_id":"GK_RF_2","article_number":"454","version_date":"1994-11-30","article_text":"1. По договору купли-продажи одна сторона (продавец) обязуется передать вещь (товар) в собственность другой стороне (покупателю), а покупатель обязуется принять этот товар и уплатить за него определенную денежную сумму (цену).\n\n2. К купле-продаже ценных бумаг и валютных ценностей положения, предусмотренные настоящим параграфом, применяются, если законом не установлены специальные правила их купли-продажи.\n\n3. В случаях, предусмотренных настоящим Кодексом или иным законом, особенности купли и продажи товаров отдельных видов определяются законами и иными правовыми актами.","article_title":"Статья 454. Договор купли-продажи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bfdb774f7632775da2cfa5c068ad96437f0ab60846b68c7662080664744c2923"},{"code_id":"GK_RF_2","article_number":"455","version_date":"1994-11-30","article_text":"1. Товаром по договору купли-продажи могут быть любые вещи с соблюдением правил, предусмотренных статьей 129 настоящего Кодекса.\n\n2. Договор может быть заключен на куплю-продажу товара, имеющегося в наличии у продавца в момент заключения договора, а также товара, который будет создан или приобретен продавцом в будущем, если иное не установлено законом или не вытекает из характера товара.\n\n3. Условие договора купли-продажи о товаре считается согласованным, если договор позволяет определить наименование и количество товара.","article_title":"Статья 455. Условие договора о товаре","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"23a0a7352b132c7babc5f78ad61dd642e56a04d970dbd67d66976b73b050c795"},{"code_id":"GK_RF_2","article_number":"456","version_date":"1994-11-30","article_text":"1. Продавец обязан передать покупателю товар, предусмотренный договором купли-продажи.\n\n2. Если иное не предусмотрено договором купли-продажи, продавец обязан одновременно с передачей вещи передать покупателю ее принадлежности, а также относящиеся к ней документы (технический паспорт, сертификат качества, инструкцию по эксплуатации и т.п.), предусмотренные законом, иными правовыми актами или договором.","article_title":"Статья 456. Обязанности продавца по передаче товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"161ac352b7c6c62c8ba4adcc70041f44c8da42894bf4ab386bc6972addbd813f"},{"code_id":"GK_RF_2","article_number":"457","version_date":"1994-11-30","article_text":"1. Срок исполнения продавцом обязанности передать товар покупателю определяется договором купли-продажи, а если договор не позволяет определить этот срок, в соответствии с правилами, предусмотренными статьей 314 настоящего Кодекса.\n\n2. Договор купли-продажи признается заключенным с условием его исполнения к строго определенному сроку, если из договора ясно вытекает, что при нарушении срока его исполнения покупатель утрачивает интерес к договору.\n\nПродавец вправе исполнять такой договор до наступления или после истечения определенного в нем срока только с согласия покупателя.","article_title":"Статья 457. Срок исполнения обязанности передать товар","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5346c1c68df1606258d89a30ccbe476e4590a471701cb72e3f1fee22682ee8f1"},{"code_id":"GK_RF_2","article_number":"458","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором купли-продажи, обязанность продавца передать товар покупателю считается исполненной в момент:\n\nвручения товара покупателю или указанному им лицу, если договором предусмотрена обязанность продавца по доставке товара;\n\nпредоставления товара в распоряжение покупателя, если товар должен быть передан покупателю или указанному им лицу в месте нахождения товара. Товар считается предоставленным в распоряжение покупателя, когда к сроку, предусмотренному договором, товар готов к передаче в надлежащем месте и покупатель в соответствии с условиями договора осведомлен о готовности товара к передаче. Товар не признается готовым к передаче, если он не идентифицирован для целей договора путем маркировки или иным образом.\n\n2. В случаях, когда из договора купли-продажи не вытекает обязанность продавца по доставке товара или передаче товара в месте его нахождения покупателю, обязанность продавца передать товар покупателю считается исполненной в момент сдачи товара перевозчику или организации связи для доставки покупателю, если договором не предусмотрено иное.","article_title":"Статья 458. Момент исполнения обязанности продавца передать товар","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"be3775c37b5097afa329ebc756ae69fcb25f9532b5d48576590b121c012902d7"},{"code_id":"GK_RF_2","article_number":"459","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором купли-продажи, риск случайной гибели или случайного повреждения товара переходит на покупателя с момента, когда в соответствии с законом или договором продавец считается исполнившим свою обязанность по передаче товара покупателю.\n\n2. Риск случайной гибели или случайного повреждения товара, проданного во время его нахождения в пути, переходит на покупателя с момента заключения договора купли-продажи, если иное не предусмотрено таким договором или обычаями делового оборота.\n\nУсловие договора о том, что риск случайной гибели или случайного повреждения товара переходит на покупателя с момента сдачи товара первому перевозчику, по требованию покупателя может быть признано судом недействительным, если в момент заключения договора продавец знал или должен был знать, что товар утрачен или поврежден, и не сообщил об этом покупателю.","article_title":"Статья 459. Переход риска случайной гибели товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"423f9ce7c16b79f434f54ef3a660483da4ec19ad9cbc2e4bf42366cacb7e56eb"},{"code_id":"GK_RF_2","article_number":"460","version_date":"1994-11-30","article_text":"1. Продавец обязан передать покупателю товар свободным от любых прав третьих лиц, за исключением случая, когда покупатель согласился принять товар, обремененный правами третьих лиц.\n\nНеисполнение продавцом этой обязанности дает покупателю право требовать уменьшения цены товара либо расторжения договора купли-продажи, если не будет доказано, что покупатель знал или должен был знать о правах третьих лиц на этот товар.\n\n2. Правила, предусмотренные пунктом 1 настоящей статьи, соответственно применяются и в том случае, когда в отношении товара к моменту его передачи покупателю имелись притязания третьих лиц, о которых продавцу было известно, если эти притязания впоследствии признаны в установленном порядке правомерными.","article_title":"Статья 460. Обязанность продавца передать товар свободным от прав третьих лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"85012bb33d483f3409cdcd59d317ca0489d17230fe015d0b421199906138ed32"},{"code_id":"GK_RF_2","article_number":"461","version_date":"1994-11-30","article_text":"1. При изъятии товара у покупателя третьими лицами по основаниям, возникшим до исполнения договора купли-продажи, продавец обязан возместить покупателю понесенные им убытки, если не докажет, что покупатель знал или должен был знать о наличии этих оснований.\n\n2. Соглашение сторон об освобождении продавца от ответственности в случае истребования приобретенного товара у покупателя третьими лицами или о ее ограничении недействительно.","article_title":"Статья 461. Ответственность продавца в случае изъятия товара у покупателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cb2723968839197f9c6d76d8e4e670e495635767af12655f56479b3b4e0e10fe"},{"code_id":"GK_RF_2","article_number":"462","version_date":"1994-11-30","article_text":"Если третье лицо по основанию, возникшему до исполнения договора купли-продажи, предъявит к покупателю иск об изъятии товара, покупатель обязан привлечь продавца к участию в деле, а продавец обязан вступить в это дело на стороне покупателя.\n\nНепривлечение покупателем продавца к участию в деле освобождает продавца от ответственности перед покупателем, если продавец докажет, что, приняв участие в деле, он мог бы предотвратить изъятие проданного товара у покупателя.\n\nПродавец, привлеченный покупателем к участию в деле, но не принявший в нем участия, лишается права доказывать неправильность ведения дела покупателем.","article_title":"Статья 462. Обязанности покупателя и продавца в случае предъявления иска об изъятии товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7c76e8b490be4c298efd07c4b8a2748c284ca35b7a52e9e84bf843428834308e"},{"code_id":"GK_RF_2","article_number":"463","version_date":"1994-11-30","article_text":"1. Если продавец отказывается передать покупателю проданный товар, покупатель вправе отказаться от исполнения договора купли-продажи.\n\n2. При отказе продавца передать индивидуально-определенную вещь покупатель вправе предъявить продавцу требования, предусмотренные статьей 398 настоящего Кодекса.","article_title":"Статья 463. Последствия неисполнения обязанности передать товар","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c5c1f48c07ac32b9291fd495cc88cc5a79b3b7049adb18d0c518118b2df8a9e8"},{"code_id":"GK_RF_2","article_number":"464","version_date":"1994-11-30","article_text":"Если продавец не передает или отказывается передать покупателю относящиеся к товару принадлежности или документы, которые он должен передать в соответствии с законом, иными правовыми актами или договором купли-продажи (пункт 2 статьи 456), покупатель вправе назначить ему разумный срок для их передачи.\n\nВ случае, когда принадлежности или документы, относящиеся к товару, не переданы продавцом в указанный срок, покупатель вправе отказаться от товара, если иное не предусмотрено договором.","article_title":"Статья 464. Последствия неисполнения обязанности передать принадлежности и документы, относящиеся к товару","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90ea730bd3b73bdfc674759ed4b73370835c2ddc8b268456a5ada9383388d63c"},{"code_id":"GK_RF_2","article_number":"465","version_date":"1994-11-30","article_text":"1. Количество товара, подлежащего передаче покупателю, предусматривается договором купли-продажи в соответствующих единицах измерения или в денежном выражении. Условие о количестве товара может быть согласовано путем установления в договоре порядка его определения.\n\n2. Если договор купли-продажи не позволяет определить количество подлежащего передаче товара, договор не считается заключенным.","article_title":"Статья 465. Количество товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4b58a778c8348bdd27c7fead9979c983038ca0aadd9339ed30dea98ac3d6a91"},{"code_id":"GK_RF_2","article_number":"466","version_date":"1994-11-30","article_text":"1. Если продавец передал в нарушение договора купли-продажи покупателю меньшее количество товара, чем определено договором, покупатель вправе, если иное не предусмотрено договором, либо потребовать передать недостающее количество товара, либо отказаться от переданного товара и от его оплаты, а если товар оплачен, потребовать возврата уплаченной денежной суммы.\n\n2. Если продавец передал покупателю товар в количестве, превышающем указанное в договоре купли-продажи, покупатель обязан известить об этом продавца в порядке, предусмотренном пунктом 1 статьи 483 настоящего Кодекса. В случае, когда в разумный срок после получения сообщения покупателя продавец не распорядится соответствующей частью товара, покупатель вправе, если иное не предусмотрено договором, принять весь товар.\n\n3. В случае принятия покупателем товара в количестве, превышающем указанное в договоре купли-продажи (пункт 2 настоящей статьи), дополнительно принятый товар оплачивается по цене, определенной для товара, принятого в соответствии с договором, если иная цена не определена соглашением сторон.","article_title":"Статья 466. Последствия нарушения условия о количестве товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a7e1f800df754413154e674673594a55095aa45d49951936a9e2443b20b6b17d"},{"code_id":"GK_RF_2","article_number":"467","version_date":"1994-11-30","article_text":"1. Если по договору купли-продажи передаче подлежат товары в определенном соотношении по видам, моделям, размерам, цветам или иным признакам (ассортимент), продавец обязан передать покупателю товары в ассортименте, согласованном сторонами.\n\n2. Если ассортимент в договоре купли-продажи не определен и в договоре не установлен порядок его определения, но из существа обязательства вытекает, что товары должны быть переданы покупателю в ассортименте, продавец вправе передать покупателю товары в ассортименте исходя из потребностей покупателя, которые были известны продавцу на момент заключения договора, или отказаться от исполнения договора.","article_title":"Статья 467. Ассортимент товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c59c0c0649ba49be88ffd2173819625f9906eb2294a810de658ab907eea7e3a"},{"code_id":"GK_RF_2","article_number":"468","version_date":"1994-11-30","article_text":"1. При передаче продавцом предусмотренных договором купли-продажи товаров в ассортименте, не соответствующем договору, покупатель вправе отказаться от их принятия и оплаты, а если они оплачены, потребовать возврата уплаченной денежной суммы.\n\n2. Если продавец передал покупателю наряду с товарами, ассортимент которых соответствует договору купли-продажи, товары с нарушением условия об ассортименте, покупатель вправе по своему выбору:\n\nпринять товары, соответствующие условию об ассортименте, и отказаться от остальных товаров;\n\nотказаться от всех переданных товаров;\n\nпотребовать заменить товары, не соответствующие условию об ассортименте, товарами в ассортименте, предусмотренном договором;\n\nпринять все переданные товары.\n\n3. При отказе от товаров, ассортимент которых не соответствует условию договора купли-продажи, или предъявлении требования о замене товаров, не соответствующих условию об ассортименте, покупатель вправе также отказаться от оплаты этих товаров, а если они оплачены, потребовать возврата уплаченной денежной суммы.\n\n4. Товары, не соответствующие условию договора купли-продажи об ассортименте, считаются принятыми, если покупатель в разумный срок после их получения не сообщит продавцу о своем отказе от товаров.\n\n5. Если покупатель не отказался от товаров, ассортимент которых не соответствует договору купли-продажи, он обязан их оплатить по цене, согласованной с продавцом. В случае, когда продавцом не приняты необходимые меры по согласованию цены в разумный срок, покупатель оплачивает товары по цене, которая в момент заключения договора при сравнимых обстоятельствах обычно взималась за аналогичные товары.\n\n6. Правила настоящей статьи применяются, если иное не предусмотрено договором купли-продажи.","article_title":"Статья 468. Последствия нарушения условия об ассортименте товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8e4eb88d65424ac6731d7952f38b041b3b357bbd2b045918ce30ff13004c7471"},{"code_id":"GK_RF_2","article_number":"469","version_date":"1994-11-30","article_text":"1. Продавец обязан передать покупателю товар, качество которого соответствует договору купли-продажи.\n\n2. При отсутствии в договоре купли-продажи условий о качестве товара продавец обязан передать покупателю товар, пригодный для целей, для которых товар такого рода обычно используется.\n\nЕсли продавец при заключении договора был поставлен покупателем в известность о конкретных целях приобретения товара, продавец обязан передать покупателю товар, пригодный для использования в соответствии с этими целями.\n\n3. При продаже товара по образцу и (или) по описанию продавец обязан передать покупателю товар, который соответствует образцу и (или) описанию.\n\nПо соглашению между продавцом и покупателем может быть передан товар, соответствующий повышенным требованиям к качеству по сравнению с обязательными требованиями, предусмотренными законом или в установленном им порядке. (В редакции Федерального закона от 17.12.1999 № 213-ФЗ)","article_title":"Статья 469. Качество товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"95c0bd8514cb93253e57bae64ceeae9785061fe3c0e600e26773d53794cff0c2"},{"code_id":"GK_RF_2","article_number":"470","version_date":"1994-11-30","article_text":"1. Товар, который продавец обязан передать покупателю, должен соответствовать требованиям, предусмотренным статьей 469 настоящего Кодекса, в момент передачи покупателю, если иной момент определения соответствия товара этим требованиям не предусмотрен договором купли-продажи, и в пределах разумного срока должен быть пригодным для целей, для которых товары такого рода обычно используются.\n\n2. В случае, когда договором купли-продажи предусмотрено предоставление продавцом гарантии качества товара, продавец обязан передать покупателю товар, который должен соответствовать требованиям, предусмотренным статьей 469 настоящего Кодекса, в течение определенного времени, установленного договором (гарантийного срока).\n\n3. Гарантия качества товара распространяется и на все составляющие его части (комплектующие изделия), если иное не предусмотрено договором купли-продажи.","article_title":"Статья 470. Гарантия качества товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81e68e5355f3489cda2fed7309cb3dea5daf9687f4353352afd07255d93718f0"},{"code_id":"GK_RF_2","article_number":"471","version_date":"1994-11-30","article_text":"1. Гарантийный срок начинает течь с момента передачи товара покупателю (статья 457), если иное не предусмотрено договором купли-продажи.\n\n2. Если покупатель лишен возможности использовать товар, в отношении которого договором установлен гарантийный срок, по обстоятельствам, зависящим от продавца, гарантийный срок не течет до устранения соответствующих обстоятельств продавцом.\n\nЕсли иное не предусмотрено договором, гарантийный срок продлевается на время, в течение которого товар не мог использоваться из-за обнаруженных в нем недостатков, при условии извещения продавца о недостатках товара в порядке, установленном статьей 483 настоящего Кодекса.\n\n3. Если иное не предусмотрено договором купли-продажи, гарантийный срок на комплектующее изделие считается равным гарантийному сроку на основное изделие и начинает течь одновременно с гарантийным сроком на основное изделие.\n\n4. На товар (комплектующее изделие), переданный продавцом взамен товара (комплектующего изделия), в котором в течение гарантийного срока были обнаружены недостатки (статья 476), устанавливается гарантийный срок той же продолжительности, что и на замененный, если иное не предусмотрено договором купли-продажи.","article_title":"Статья 471. Исчисление гарантийного срока","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e1ea8aae5e9e83f42e407b27f83e3cc23180fa3d8179565e02158341ff90f6a"},{"code_id":"GK_RF_2","article_number":"473","version_date":"1994-11-30","article_text":"Срок годности товара определяется периодом времени, исчисляемым со дня его изготовления, в течение которого товар пригоден к использованию, либо датой, до наступления которой товар пригоден к использованию.","article_title":"Статья 473. Исчисление срока годности товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6bd66cbc3aebf79b34553035f0497811cd032f11feb9f9f833d6ad1eb5fe871e"},{"code_id":"GK_RF_2","article_number":"474","version_date":"1994-11-30","article_text":"1. Проверка качества товара может быть предусмотрена законом, иными правовыми актами, обязательными требованиями, установленными в соответствии с законодательством Российско\n\nй Федерации о техническом регулировании, или договором купли-продажи. (В редакции Федерального закона от 19.07.2011 № 248-ФЗ)\n\nПорядок проверки качества товара устанавливается законом, иными правовыми актами, обязательными требованиями, установленными в соответствии с законодательством Российской Федерации о техническом регулировании, или договором. В случаях, когда порядок проверки установлен законом, иными правовыми актами, обязательными требованиями, установленными в соответствии с законодательством Российской Федерации о техническом регулировании порядок проверки качества товаров, определяемый договором, должен соответствовать этим требованиям. (В редакции Федерального закона от 19.07.2011 № 248-ФЗ)\n\n2. Если порядок проверки качества товара не установлен в соответствии с пунктом 1 настоящей статьи, то проверка качества товара производится в соответствии с обычаями делового оборота или иными обычно применяемыми условиями проверки товара, подлежащего передаче по договору купли-продажи.","article_title":"Статья 474. Проверка качества товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"73fd6aceca11753ef015c75734338a0f2e8b13e0c889a8c061a7a1048e91f843"},{"code_id":"GK_RF_2","article_number":"475","version_date":"1994-11-30","article_text":"1. Если недостатки товара не были оговорены продавцом, покупатель, которому передан товар ненадлежащего качества, вправе по своему выбору потребовать от продавца:\n\nсоразмерного уменьшения покупной цены;\n\nбезвозмездного устранения недостатков товара в разумный срок;\n\nвозмещения своих расходов на устранение недостатков товара.\n\n2. В случае существенного нарушения требований к качеству товара (обнаружения неустранимых недостатков, недостатков, которые не могут быть устранены без несоразмерных расходов или затрат времени, или выявляются неоднократно, либо проявляются вновь после их устранения, и других подобных недостатков) покупатель вправе по своему выбору:\n\nотказаться от исполнения договора купли-продажи и потребовать возврата уплаченной за товар денежной суммы;\n\nпотребовать замены товара ненадлежащего качества товаром, соответствующим договору.\n\n3. Требования об устранении недостатков или о замене товара, указанные в пунктах 1 и 2 настоящей статьи, могут быть предъявлены покупателем, если иное не вытекает из характера товара или существа обязательства.\n\n4. В случае ненадлежащего качества части товаров, входящих в комплект (статья 479), покупатель вправе осуществить в отношении этой части товаров права, предусмотренные пунктами 1 и 2 настоящей статьи.\n\n5. Правила, предусмотренные настоящей статьей, применяются, если настоящим Кодексом или другим законом не установлено иное.","article_title":"Статья 475. Последствия передачи товара ненадлежащего качества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"21b40d54556906d11eb6ffdc15b01ca61b5a4c21119f605af1b2fe9a8dd7ff8f"},{"code_id":"GK_RF_2","article_number":"476","version_date":"1994-11-30","article_text":"1. Продавец отвечает за недостатки товара, если покупатель докажет, что недостатки товара возникли до его передачи покупателю или по причинам, возникшим до этого момента.\n\n2. В отношении товара, на который продавцом предоставлена гарантия качества, продавец отвечает за недостатки товара, если не докажет, что недостатки товара возникли после его передачи покупателю вследствие нарушения покупателем правил пользования товаром или его хранения, либо действий третьих лиц, либо непреодолимой силы.","article_title":"Статья 476. Недостатки товара, за которые отвечает продавец","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3067e2d4dd66165e4291c1b83da94305e3088831b851d865e1de3b48ed014852"},{"code_id":"GK_RF_2","article_number":"477","version_date":"1994-11-30","article_text":"1. Если иное не установлено законом или договором купли-продажи, покупатель вправе предъявить требования, связанные с недостатками товара, при условии, что они обнаружены в сроки, установленные настоящей статьей.\n\n2. Если на товар не установлен гарантийный срок или срок годности, требования, связанные с недостатками товара, могут быть предъявлены покупателем при условии, что недостатки проданного товара были обнаружены в разумный срок, но в пределах двух лет со дня передачи товара покупателю либо в пределах более длительного срока, когда такой срок установлен законом или договором купли-продажи. Срок для выявления недостатков товара, подлежащего перевозке или отправке по почте, исчисляется со дня доставки товара в место его назначения.\n\n3. Если на товар установлен гарантийный срок, покупатель вправе предъявить требования, связанные с недостатками товара, при обнаружении недостатков в течение гарантийного срока.\n\nВ случае, когда на комплектующее изделие в договоре купли-продажи установлен гарантийный срок меньшей продолжительности, чем на основное изделие, покупатель вправе предъявить требования, связанные с недостатками комплектующего изделия, при их обнаружении в течение гарантийного срока на основное изделие.\n\nЕсли на комплектующее изделие в договоре установлен гарантийный срок большей продолжительности, чем гарантийный срок на основное изделие, покупатель вправе предъявить требования, связанные с недостатками товара, если недостатки комплектующего изделия обнаружены в течение гарантийного срока на него, независимо от истечения гарантийного срока на основное изделие.\n\n4. В отношении товара, на который установлен срок годности, покупатель вправе предъявить требования, связанные с недостатками товара, если они обнаружены в течение срока годности товара.\n\n5. В случаях, когда предусмотренный договором гарантийный срок составляет менее двух лет и недостатки товара обнаружены покупателем по истечении гарантийного срока, но в пределах двух лет со дня передачи товара покупателю, продавец несет ответственность, если покупатель докажет, что недостатки товара возникли до передачи товара покупателю или по причинам, возникшим до этого момента.","article_title":"Статья 477. Сроки обнаружения недостатков переданного товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b29b529ef8d67954e950a40eeef7d3d3c355e4b3958fc8da0039209f9f33a8c3"},{"code_id":"GK_RF_2","article_number":"478","version_date":"1994-11-30","article_text":"1. Продавец обязан передать покупателю товар, соответствующий условиям договора купли-продажи о комплектности.\n\n2. В случае, когда договором купли-продажи не определена комплектность товара, продавец обязан передать покупателю товар, комплектность которого определяется обычаями делового оборота или иными обычно предъявляемыми требованиями.","article_title":"Статья 478. Комплектность товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4880671220d29fa8c04fc30932fee88c50b86d962c4a9af37f614a556b6b6554"},{"code_id":"GK_RF_2","article_number":"479","version_date":"1994-11-30","article_text":"1. Если договором купли-продажи предусмотрена обязанность продавца передать покупателю определенный набор товаров в комплекте (комплект товаров), обязательство считается исполненным с момента передачи всех товаров, включенных в комплект.\n\n2. Если иное не предусмотрено договором купли-продажи и не вытекает из существа обязательства, продавец обязан передать покупателю все товары, входящие в комплект, одновременно.","article_title":"Статья 479. Комплект товаров","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ae1ef26fbf68f98607c420ca5459ecdef65ef572931276a3ea24b4c43a9ebd4"},{"code_id":"GK_RF_2","article_number":"480","version_date":"1994-11-30","article_text":"1. В случае передачи некомплектного товара (статья 478) покупатель вправе по своему выбору потребовать от продавца:\n\nсоразмерного уменьшения покупной цены;\n\nдоукомплектования товара в разумный срок.\n\n2. Если продавец в разумный срок не выполнил требования покупателя о доукомплектовании товара, покупатель вправе по своему выбору:\n\nпотребовать замены некомплектного товара на комплектный;\n\nотказаться от исполнения договора купли-продажи и потребовать возврата уплаченной денежной суммы.\n\n3. Последствия, предусмотренные пунктами 1 и 2 настоящей статьи, применяются и в случае нарушения продавцом обязанности передать покупателю комплект товаров (статья 479), если иное не предусмотрено договором купли-продажи и не вытекает из существа обязательства.","article_title":"Статья 480. Последствия передачи некомплектного товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cac0d7ac98190830f418ab1247bb30e0669c49c93ea6127ee6b18d294dccbad7"},{"code_id":"GK_RF_2","article_number":"481","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором купли-продажи и не вытекает из существа обязательства, продавец обязан передать покупателю товар в таре и (или) упаковке, за исключением товара, который по своему характеру не требует затаривания и (или) упаковки.\n\n2. Если договором купли-продажи не определены требования к таре и упаковке, то товар должен быть затарен и (или) упакован обычным для такого товара способом, а при отсутствии такового способом, обеспечивающим сохранность товаров такого рода при обычных условиях хранения и транспортирования.\n\n3. Если в установленном законом порядке предусмотрены обязательные требования к таре и (или) упаковке, то продавец, осуществляющий предпринимательскую деятельность, обязан передать покупателю товар в таре и (или) упаковке, соответствующих этим обязательным требованиям.","article_title":"Статья 481. Тара и упаковка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d2af9c2908f98769b9abeadb0aebcb567fbf019e8814a83cbf5df229f7c8517"},{"code_id":"GK_RF_2","article_number":"482","version_date":"1994-11-30","article_text":"1. В случаях, когда подлежащий затариванию и (или) упаковке товар передается покупателю без тары и (или) упаковки либо в ненадлежащей таре и (или) упаковке, покупатель вправе потребовать от продавца затарить и (или) упаковать товар либо заменить ненадлежащую тару и (или) упаковку, если иное не вытекает из договора, существа обязательства или характера товара.\n\n2. В случаях, предусмотренных пунктом 1 настоящей статьи, покупатель вправе вместо предъявления продавцу требований, указанных в этом пункте, предъявить к нему требования, вытекающие из передачи товара ненадлежащего качества (статья 475).","article_title":"Статья 482. Последствия передачи товара без тары и (или) упаковки либо в ненадлежащей таре и (или) упаковке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9fafabd127e880a33cf5042c83a7677a77cb7cc90365d1f2ed07c0705a1d5e7d"},{"code_id":"GK_RF_2","article_number":"483","version_date":"1994-11-30","article_text":"1. Покупатель обязан известить продавца о нарушении условий договора купли-продажи о количестве, об ассортименте, о качестве, комплектности, таре и (или) об упаковке товара в срок, предусмотренный законом, иными правовыми актами или договором, а если такой срок не установлен, в разумный срок после того, как нарушение соответствующего условия договора должно было быть обнаружено исходя из характера и назначения товара.\n\n2. В случае невыполнения правила, предусмотренного пунктом 1 настоящей статьи, продавец вправе отказаться полностью или частично от удовлетворения требований покупателя о передаче ему недостающего количества товара, замене товара, не соответствующего условиям договора купли-продажи о качестве или об ассортименте, об устранении недостатков товара, о доукомплектовании товара или о замене некомплектного товара комплектным, о затаривании и (или) об упаковке товара либо о замене ненадлежащей тары и (или) упаковки товара, если докажет, что невыполнение этого правила покупателем повлекло невозможность удовлетворить его требования или влечет для продавца несоизмеримые расходы по сравнению с теми, которые он понес бы, если бы был своевременно извещен о нарушении договора.\n\n3. Если продавец знал или должен был знать о том, что переданные покупателю товары не соответствуют условиям договора купли-продажи, он не вправе ссылаться на положения, предусмотренные пунктами 1 и 2 настоящей статьи.","article_title":"Статья 483. Извещение продавца о ненадлежащем исполнении договора купли-продажи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"05ea481ec88f1f7b15df958074b80d11c8af3fd8679d35428eb71516a3906821"},{"code_id":"GK_RF_2","article_number":"484","version_date":"1994-11-30","article_text":"1. Покупатель обязан принять переданный ему товар, за исключением случаев, когда он вправе потребовать замены товара или отказаться от исполнения договора купли-продажи.\n\n2. Если иное не предусмотрено законом, иными правовыми актами или договором купли-продажи, покупатель обязан совершить действия, которые в соответствии с обычно предъявляемыми требованиями необходимы с его стороны для обеспечения передачи и получения соответствующего товара.\n\n3. В случаях, когда покупатель в нарушение закона, иных правовых актов или договора купли-продажи не принимает товар или отказывается его принять, продавец вправе потребовать от покупателя принять товар или отказаться от исполнения договора.","article_title":"Статья 484. Обязанность покупателя принять товар","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6c3b2e16fe041880daa0299443b4d5f2ed173e5fd21691d0cfc46d08a389d7f"},{"code_id":"GK_RF_2","article_number":"485","version_date":"1994-11-30","article_text":"1. Покупатель обязан оплатить товар по цене, предусмотренной договором купли-продажи, либо, если она договором не предусмотрена и не может быть определена исходя из его условий, по цене, определяемой в соответствии с пунктом 3 статьи 424 настоящего Кодекса, а также совершить за свой счет действия, которые в соответствии с законом, иными правовыми актами, договором или обычно предъявляемыми требованиями необходимы для осуществления платежа.\n\n2. Когда цена установлена в зависимости от веса товара, она определяется по весу нетто, если иное не предусмотрено договором купли-продажи.\n\n3. Если договор купли-продажи предусматривает, что цена товара подлежит изменению в зависимости от показателей, обусловливающих цену товара (себестоимость, затраты и т.п.), но при этом не определен способ пересмотра цены, цена определяется исходя из соотношения этих показателей на момент заключения договора и на момент передачи товара. При просрочке продавцом исполнения обязанности передать товар цена определяется исходя из соотношения этих показателей на момент заключения договора и на момент передачи товара, предусмотренный договором, а если он договором не предусмотрен, на момент, определенный в соответствии со статьей 314 настоящего Кодекса.\n\nПравила, предусмотренные настоящим пунктом, применяются, если иное не установлено настоящим Кодексом, другим законом, иными правовыми актами или договором и не вытекает из существа обязательства.","article_title":"Статья 485. Цена товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24320cb9cd76a4a2c079963a2d2489b7c50298564c764bb9e7aa981881175526"},{"code_id":"GK_RF_2","article_number":"486","version_date":"1994-11-30","article_text":"1. Покупатель обязан оплатить товар непосредственно до или после передачи ему продавцом товара, если иное не предусмотрено настоящим Кодексом, другим законом, иными правовыми актами или договором купли-продажи и не вытекает из существа обязательства.\n\n2. Если договором купли-продажи не предусмотрена рассрочка оплаты товара, покупатель обязан уплатить продавцу цену переданного товара полностью.\n\n3. Если покупатель своевременно не оплачивает переданный в соответствии с договором купли-продажи товар, продавец вправе потребовать оплаты товара и уплаты процентов в соответствии со статьей 395 настоящего Кодекса.\n\n4. Если покупатель в нарушение договора купли-продажи отказывается принять и оплатить товар, продавец вправе по своему выбору потребовать оплаты товара либо отказаться от исполнения договора.\n\n5. В случаях, когда продавец в соответствии с договором купли-продажи обязан передать покупателю не только товары, которые покупателем не оплачены, но и другие товары, продавец вправе приостановить передачу этих товаров до полной оплаты всех ранее переданных товаров, если иное не предусмотрено законом, иными правовыми актами или договором.","article_title":"Статья 486. Оплата товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a5a3fdda56ae1222a670bca59a252ebd3ca5c243b043366f7563d1c32ae24c6"},{"code_id":"GK_RF_2","article_number":"487","version_date":"1994-11-30","article_text":"1. В случаях, когда договором купли-продажи предусмотрена обязанность покупателя оплатить товар полностью или частично до передачи продавцом товара (предварительная оплата), покупатель должен произвести оплату в срок, предусмотренный договором, а если такой срок договором не предусмотрен, в срок, определенный в соответствии со статьей 314 настоящего Кодекса.\n\n2. В случае неисполнения покупателем обязанности предварительно оплатить товар применяются правила, предусмотренные статьей 328 настоящего Кодекса.\n\n3. В случае, когда продавец, получивший сумму предварительной оплаты, не исполняет обязанность по передаче товара в установленный срок (статья 457), покупатель вправе потребовать передачи оплаченного товара или возврата суммы предварительной оплаты за товар, не переданный продавцом.","article_title":"Статья 487. Предварительная оплата товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13a290f2c150f47308fa6b7cc7f4d015e3a0145b90442a03870695a22d5eeeed"},{"code_id":"GK_RF_2","article_number":"488","version_date":"1994-11-30","article_text":"1. В случае, когда договором купли-продажи предусмотрена оплата товара через определенное время после его передачи покупателю (продажа товара в кредит), покупатель должен произвести оплату в срок, предусмотренный договором, а если такой срок договором не предусмотрен, в срок, определенный в соответствии со статьей 314 настоящего Кодекса.\n\n2. В случае неисполнения продавцом обязанности по передаче товара применяются правила, предусмотренные статьей 328 настоящего Кодекса.\n\n3. В случае, когда покупатель, получивший товар, не исполняет обязанность по его оплате в установленный договором купли-продажи срок, продавец вправе потребовать оплаты переданного товара или возврата неоплаченных товаров.\n\n4. В случае, когда покупатель не исполняет обязанность по оплате переданного товара в установленный договором срок и иное не предусмотрено настоящим Кодексом или договором купли-продажи, на просроченную сумму подлежат уплате проценты в соответствии со статьей 395 настоящего Кодекса со дня, когда по договору товар должен был быть оплачен, до дня оплаты товара покупателем.\n\nДоговором может быть предусмотрена обязанность покупателя уплачивать проценты на сумму, соответствующую цене товара, начиная со дня передачи товара продавцом.\n\n5. Если иное не предусмотрено договором купли-продажи, с момента передачи товара покупателю и до его оплаты товар, проданный в кредит, признается находящимся в залоге у продавца для обеспечения исполнения покупателем его обязанности по оплате товара.","article_title":"Статья 488. Оплата товара, проданного в кредит","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f377531f3576d36ab9ee497c1b1733d5e9f8244c9c238df07fe3d76afdc7c3ce"},{"code_id":"GK_RF_2","article_number":"489","version_date":"1994-11-30","article_text":"1. Договором о продаже товара в кредит может быть предусмотрена оплата товара в рассрочку.\n\nДоговор о продаже товара в кредит с условием о рассрочке платежа считается заключенным, если в нем наряду с другими существенными условиями договора купли-продажи указаны цена товара, порядок, сроки и размеры платежей.\n\n2. Когда покупатель не производит в установленный договором срок очередной платеж за проданный в рассрочку и переданный ему товар, продавец вправе, если иное не предусмотрено договором, отказаться от исполнения договора и потребовать возврата проданного товара, за исключением случаев, когда сумма платежей, полученных от покупателя, превышает половину цены товара.\n\n3. К договору о продаже товара в кредит с условием о рассрочке платежа применяются правила, предусмотренные пунктами 2, 4 и 5 статьи 488 настоящего Кодекса.","article_title":"Статья 489. Оплата товара в рассрочку","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ab58c7e0cfef8131104fc7fddbf7ad4efd18782728ed5f67c38854071eaed307"},{"code_id":"GK_RF_2","article_number":"490","version_date":"1994-11-30","article_text":"Договором купли-продажи может быть предусмотрена обязанность продавца или покупателя страховать товар.\n\nВ случае, когда сторона, обязанная страховать товар, не осуществляет страхование в соответствии с условиями договора, другая сторона вправе застраховать товар и потребовать от обязанной стороны возмещения расходов на страхование либо отказаться от исполнения договора.","article_title":"Статья 490. Страхование товара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"863994778930e7315e0079b4b1a0e0246a397518f31fa0a33d88a2b64ef7607e"}]$law7d0031$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
